/-- Cayley–Weyl Operators & Steinberg Triple Unipotent Braids (File 1). -/

def steinbergBraidDualInv (P A C : B) : B :=
  (1 + coneMinus P C) * (1 - conePlus P A) * (1 + coneMinus P C)

/-- Graded Coboundary (`d_±`) and Boundary (`d̄_±`) Super-Derivations & Chiral Hodge Operators (File 3). -/

def hodgeLaplacianPhi (P A C X : B) : B :=
  superDerivPhi P A C (superDerivPhiBar P A C X) +
  superDerivPhiBar P A C (superDerivPhi P A C X)

def golay12Ext (P A C X : B) : B :=
  kantorDelta4 P A C X - kantorDelta2 P A C X

/-- **The Scale-24 Binary Golay / Leech Operator Frame (`golay24G0`, `golay24Gp1`, `golay24Gm1`, `golay24Gp2`, `golay24Gm2`):** -/

def golay24Gp1 (P A C X : B) : B :=
  ((4 : ℤ) • kantorDelta2 P A C X - kantorDelta4 P A C X) +
  (2 : ℤ) • ((4 : ℤ) • kantorDelta1 P A C X - kantorDelta3 P A C X)

def golay24Gm1 (P A C X : B) : B :=
  ((4 : ℤ) • kantorDelta2 P A C X - kantorDelta4 P A C X) -
  (2 : ℤ) • ((4 : ℤ) • kantorDelta1 P A C X - kantorDelta3 P A C X)

def golay24Gp2 (P A C X : B) : B :=
  (kantorDelta4 P A C X - kantorDelta2 P A C X) +
  (2 : ℤ) • (kantorDelta3 P A C X - kantorDelta1 P A C X)

def chiralFractalBranch (n : ℕ) (P A C : B) : B :=
  mandelbrotTower n (qgtPlus P A C) - mandelbrotTower n (qgtMinus P A C)

/-- Lemma A₆₆.1: Invariance of the 6-Fold Cone–Sheet Braiding System Under `idemDefect`. -/

def moebiusConjDual (P A C X : B) : B :=
  moebiusBruhatDual P A C * X * moebiusBruhatDualInv P A C

/-- **Full 3-Factor Non-Abelian Steinberg Aberrator (`steinbergConj P A C X = B_+ X B_+⁻¹`):** -/

def steinbergConj (P A C X : B) : B :=
  steinbergBraid P A C * X * steinbergBraidInv P A C

/-- **Dual 3-Factor Non-Abelian Steinberg Aberrator (`steinbergConjDual P A C X = B_- X B_-⁻¹`):** -/

def diracBra (P A : B) : B := coneMinus P (star A)

